<template>
  <section v-loading="loading" class="annual-leave-panel">
    <p class="annual-note">额度规则：6月30日及之前入职首年1天；之后入职首年0天、次年1月1日先获1天（仅一次）。所有人员此后每满周年再过3个月加1天，上限10天。</p>
    <div class="annual-toolbar"><el-input-number v-model="year" :min="2000" :max="currentYear+1" :precision="0" :controls="false" aria-label="年假抵扣年份" @change="load" /><el-input v-model="keyword" placeholder="搜索姓名、账号、事由" clearable aria-label="年假记录搜索" @keyup.enter="search" @clear="search" /><el-button @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button @click="load">刷新</el-button><AttendanceRulesPopover /></div>
    <p class="annual-note">请假（含迟到折算）优先抵扣已生效年假；余额不足部分待补班。人事可改为“不扣年假、扣工资”，也可恢复自动抵扣。已抵年假或明确扣工资的时间不重复补班。按自然年、发生日期先后分配，未来请假单独显示预留；1天按当日本人完整班次时长折算。扣工资记录为时长，工资金额按后续薪酬核算。</p>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-table :data="people" border><el-table-column v-if="admin" prop="name" label="姓名" min-width="110" /><el-table-column label="本年已生效额度" min-width="135"><template #default="{row}">{{daysLabel(row.annual_leave_days)}}</template></el-table-column><el-table-column label="已抵扣年假" min-width="120"><template #default="{row}">{{daysLabel(row.used_days)}}</template></el-table-column><el-table-column label="未来请假预留" min-width="130"><template #default="{row}">{{daysLabel(row.reserved_days)}}</template></el-table-column><el-table-column label="可用年假" min-width="120"><template #default="{row}">{{daysLabel(row.remaining_days)}}</template></el-table-column><el-table-column label="扣工资时长" min-width="120"><template #default="{row}">{{durationLabel(row.wage_minutes)}}</template></el-table-column><el-table-column label="待补班时长" min-width="120"><template #default="{row}">{{durationLabel(row.makeup_required_minutes)}}</template></el-table-column><el-table-column label="年度调整记录" fixed="right" width="150"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link type="primary">全部调整记录（{{row.history?.length||0}}）</el-button></template><div class="annual-detail"><h4>{{row.name}} · {{year}}年全部调整记录</h4><p v-if="!row.history?.length">暂无手动调整。</p><article v-for="item in row.history" :key="item.id"><el-descriptions :column="2" border size="small"><el-descriptions-item label="调整人">{{item.actor_name}}</el-descriptions-item><el-descriptions-item label="时间">{{formatBusinessDateTime(item.created_at)}}</el-descriptions-item><el-descriptions-item label="来源" :span="2">{{item.source_key}}</el-descriptions-item><el-descriptions-item label="原方式">{{modeLabel(item.before_mode)}}</el-descriptions-item><el-descriptions-item label="调整后">{{modeLabel(item.after_mode)}}</el-descriptions-item><el-descriptions-item label="原因" :span="2">{{item.reason}}</el-descriptions-item></el-descriptions><p>年假抵扣 {{durationLabel(sourceMinutes(item.before_snapshot,item.source_key,'annual_minutes'))}} → {{durationLabel(sourceMinutes(item.after_snapshot,item.source_key,'annual_minutes'))}}；扣工资 {{durationLabel(sourceMinutes(item.before_snapshot,item.source_key,'wage_minutes'))}} → {{durationLabel(sourceMinutes(item.after_snapshot,item.source_key,'wage_minutes'))}}</p></article></div></el-popover></template></el-table-column></el-table>
    <h4>每次请假抵扣明细</h4>
    <el-table :data="entries" border max-height="520">
      <el-table-column v-if="admin" prop="name" label="姓名" min-width="110" /><el-table-column prop="day" label="归属日期" width="110" />
      <el-table-column label="来源" min-width="130"><template #default="{row}"><el-tag :type="row.source_kind==='lateness'?'warning':'info'">{{row.source_kind==='lateness'?'迟到折算请假':'申请请假'}}</el-tag><el-tag v-if="row.future" size="small">未来预留</el-tag></template></el-table-column>
      <el-table-column label="请假时长" min-width="110"><template #default="{row}">{{durationLabel(row.minutes)}}</template></el-table-column><el-table-column label="抵扣年假" min-width="125"><template #default="{row}">{{durationLabel(row.annual_minutes)}}（{{row.annual_days}}天）</template></el-table-column><el-table-column label="扣工资" min-width="110"><template #default="{row}">{{durationLabel(row.wage_minutes)}}</template></el-table-column><el-table-column label="待补班" min-width="110"><template #default="{row}">{{durationLabel(row.makeup_required_minutes)}}</template></el-table-column><el-table-column label="当前方式" min-width="160"><template #default="{row}">{{modeLabel(row.mode)}}<span v-if="row.quota_pending">（入职时间或班次待完善）</span></template></el-table-column><el-table-column prop="reason" label="请假事由" min-width="170" show-overflow-tooltip />
      <el-table-column label="详情" fixed="right" width="100"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link type="primary">查看详情</el-button></template><div class="annual-detail"><h4>{{row.name}} · {{row.day}} 请假抵扣详情</h4><el-descriptions :column="2" border size="small"><el-descriptions-item label="来源标识" :span="2">{{row.source_key}}</el-descriptions-item><el-descriptions-item label="本日完整班次">{{durationLabel(row.day_minutes)}}</el-descriptions-item><el-descriptions-item label="请假时长">{{durationLabel(row.minutes)}}</el-descriptions-item><el-descriptions-item label="抵扣年假">{{durationLabel(row.annual_minutes)}}（{{row.annual_days}}天）</el-descriptions-item><el-descriptions-item label="扣工资">{{durationLabel(row.wage_minutes)}}</el-descriptions-item><el-descriptions-item label="待补班">{{durationLabel(row.makeup_required_minutes)}}</el-descriptions-item><el-descriptions-item label="当前方式">{{modeLabel(row.mode)}}</el-descriptions-item></el-descriptions><p v-if="row.spans?.length" v-for="(span,index) in row.spans" :key="index">迟到区间：{{formatBusinessDateTime(span.start_at)}} 至 {{formatBusinessDateTime(span.end_at)}}</p><p>事由：{{row.reason||'-'}}</p><p>调整按整次来源生效：同一张请假申请的所有日期统一调整；迟到按本次打卡来源调整。完整调整记录见右侧“调整记录”。</p></div></el-popover></template></el-table-column>
      <el-table-column label="调整记录" fixed="right" width="120"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link type="primary">调整记录（{{row.history?.length||0}}）</el-button></template><div class="annual-detail"><h4>{{row.name}} · 抵扣方式调整记录</h4><p v-if="!row.history?.length">暂无手动调整，按年假优先自动抵扣。</p><article v-for="item in row.history" :key="item.id"><el-descriptions :column="2" border size="small"><el-descriptions-item label="调整人">{{item.actor_name}}</el-descriptions-item><el-descriptions-item label="调整时间">{{formatBusinessDateTime(item.created_at)}}</el-descriptions-item><el-descriptions-item label="原方式">{{modeLabel(item.before_mode)}}</el-descriptions-item><el-descriptions-item label="调整后">{{modeLabel(item.after_mode)}}</el-descriptions-item><el-descriptions-item label="原因" :span="2">{{item.reason}}</el-descriptions-item></el-descriptions><p>本次来源年假抵扣：{{durationLabel(sourceMinutes(item.before_snapshot,row.source_key,'annual_minutes'))}} → {{durationLabel(sourceMinutes(item.after_snapshot,row.source_key,'annual_minutes'))}}；扣工资：{{durationLabel(sourceMinutes(item.before_snapshot,row.source_key,'wage_minutes'))}} → {{durationLabel(sourceMinutes(item.after_snapshot,row.source_key,'wage_minutes'))}}</p><p>保存时的前后分配快照已留存；释放的年假会按日期顺序供其他请假自动抵扣。</p></article></div></el-popover></template></el-table-column>
      <el-table-column v-if="admin" label="操作" fixed="right" width="120"><template #default="{row}"><el-button link type="primary" :disabled="!desktop||!row.ready" @click="edit(row)">调整抵扣</el-button></template></el-table-column>
    </el-table>
    <DraggableFormDialog v-model="visible" title="调整请假抵扣方式" append-to-body width="min(720px, calc(100vw - 32px))" top="5vh" class="leave-settlement-dialog" :close-on-click-modal="false" :before-close="close">
      <AppForm ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="人员与请假来源"><ReadonlyField :model-value="target?`${target.name} · ${target.source_key}`:''" source="auto" /></el-form-item><el-form-item label="抵扣方式" prop="mode"><el-radio-group v-model="form.mode" :disabled="saving"><el-radio value="auto">自动：年假优先，不足待补班</el-radio><el-radio value="wage">不扣年假，扣工资</el-radio></el-radio-group></el-form-item><el-form-item label="调整原因" prop="reason"><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="1000" show-word-limit :disabled="saving" /></el-form-item></AppForm><el-alert title="本次调整对同一张请假申请全部日期（含跨年）生效；迟到则只针对本次打卡来源。保存调整人、时间、原因和前后分配快照，自动重新分配受影响年假及补班额度。" :closable="false" /><el-alert v-if="submitError" :title="submitError" type="error" :closable="false" />
      <template #footer><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存调整并留记录</el-button></template>
    </DraggableFormDialog>
  </section>
</template>
<script setup>
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import DraggableFormDialog from '@/components/common/DraggableFormDialog.vue'
import ReadonlyField from '@/components/common/ReadonlyField.vue'
import AttendanceRulesPopover from '@/components/common/AttendanceRulesPopover.vue'
import {getAnnualLeave,saveLeaveSettlement} from '@/api/attendance'
import {durationLabel} from '@/utils/attendance'
import {formatBusinessDateTime,businessDateTimeInputValue} from '@/utils/dateTime'
import {chatClientType} from '@/utils/chatDevice'
import {matchesSearchFields} from '@/utils/searchMatching'
import {subscribe} from '@/utils/realtimeSocket'
const props=defineProps({admin:Boolean}),desktop=chatClientType(navigator)==='desktop',currentYear=Number(businessDateTimeInputValue(new Date()).slice(0,4)),year=ref(currentYear),keyword=ref(''),effectiveKeyword=ref(''),data=ref({}),loading=ref(false),error=ref(''),visible=ref(false),saving=ref(false),target=ref(null),formRef=ref(),submitError=ref('')
const form=reactive({id:'leave-settlement',client_id:'',mode:'wage',reason:''}),rules={mode:[{required:true,message:'请选择抵扣方式',trigger:'change'}],reason:[{required:true,whitespace:true,message:'请填写调整原因',trigger:'blur'}]}
const allEntries=computed(()=>(data.value.people||[]).flatMap(person=>(person.entries||[]).map(entry=>({...entry,name:person.name,username:person.username,ready:person.ready})))),entries=computed(()=>allEntries.value.filter(row=>matchesSearchFields([row.name,row.username,row.reason],effectiveKeyword.value))),people=computed(()=>(data.value.people||[]).filter(person=>matchesSearchFields([person.name,person.username,...(person.entries||[]).map(row=>row.reason)],effectiveKeyword.value)))
const modeLabel=value=>value==='wage'?'不扣年假，扣工资':'年假优先，不足待补班',daysLabel=value=>value==null?'待填写入职时间':`${Number(value.toFixed?.(6)??value)}天`
function sourceMinutes(snapshot,key,field){return Object.values(snapshot||{}).reduce((sum,year)=>sum+(year.entries||[]).filter(row=>row.source_key===key).reduce((total,row)=>total+(row[field]||0),0),0)}
let controller,sequence=0,alive=true,timer,unsubscribe
async function load(){controller?.abort();controller=new AbortController();const id=++sequence;loading.value=true;error.value='';try{const value=await getAnnualLeave(year.value,props.admin,{signal:controller.signal});if(alive&&id===sequence)data.value=value}catch(e){if(alive&&id===sequence&&e.code!=='ERR_CANCELED')error.value=typeof e.detail==='string'?e.detail:'读取年假抵扣失败'}finally{if(alive&&id===sequence)loading.value=false}}
function search(){clearTimeout(timer);effectiveKeyword.value=keyword.value}
function reset(){keyword.value='';search()}
function edit(row){target.value=row;Object.assign(form,{id:`leave-settlement:${row.source_key}`,client_id:crypto.randomUUID(),mode:row.mode==='wage'?'auto':'wage',reason:''});submitError.value='';visible.value=true}
function close(done){if(!saving.value)done()}
async function save(){if(saving.value||!await formRef.value.validate().catch(()=>false))return;saving.value=true;submitError.value='';try{const result=await saveLeaveSettlement({client_id:form.client_id,source_kind:target.value.source_kind,source_id:target.value.source_id,mode:form.mode,revision:target.value.revision,reason:form.reason});ElMessage.success(result.message);visible.value=false;window.dispatchEvent(new Event('annual-leave-changed'));load()}catch(e){submitError.value=typeof e.detail==='string'?e.detail:'调整未确认保存，请重试'}finally{saving.value=false}}
watch(keyword,value=>{clearTimeout(timer);if(!value)search();else timer=setTimeout(search,400)})
onMounted(()=>{load();unsubscribe=subscribe('annual_leave_changed',load);window.addEventListener('focus',load);window.addEventListener('attendance-leave-changed',load);window.addEventListener('attendance-clock-changed',load)})
onBeforeUnmount(()=>{alive=false;sequence++;controller?.abort();clearTimeout(timer);unsubscribe?.();window.removeEventListener('focus',load);window.removeEventListener('attendance-leave-changed',load);window.removeEventListener('attendance-clock-changed',load)})
</script>
<style scoped>.annual-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}.annual-toolbar>.el-input{width:240px}.annual-note{font-size:13px;line-height:1.8;color:#64748b}.annual-detail{max-height:560px;overflow-y:auto;overflow-wrap:anywhere}.annual-detail article{border-bottom:1px solid #e2e8f0;padding:10px 0}.el-table{margin:12px 0}</style>
<style>.leave-settlement-dialog.el-dialog{display:flex;flex-direction:column;max-height:90vh;overflow:hidden}.leave-settlement-dialog>.el-dialog__header,.leave-settlement-dialog>.el-dialog__footer{flex-shrink:0}.leave-settlement-dialog>.el-dialog__body{flex:1;min-height:0;overflow-y:auto}.leave-settlement-dialog>.el-dialog__footer{border-top:1px solid #e2e8f0;background:#f8fafc}</style>
